<?php

declare(strict_types=1);

if (! function_exists('timb_manifest')) {
    /**
     * The image set: dimensions and titles, keyed by image key.
     *
     * app/Data/ImageManifest.php is generated by tools/optimize_images.py and
     * is the fallback. Rows from the media library are merged over it, so an
     * image uploaded through the CMS is usable straight away, and a title
     * edited there takes effect without regenerating the file.
     */
    function timb_manifest(): array
    {
        static $manifest = null;

        if ($manifest !== null) {
            return $manifest;
        }

        $file = require APPPATH . 'Data/ImageManifest.php';

        try {
            $stored = App\Models\MediaModel::manifestRows();
        } catch (\Throwable $e) {
            log_message('error', 'Media library unavailable, using the generated manifest: ' . $e->getMessage());
            $stored = [];
        }

        return $manifest = $stored === [] ? $file : $stored + $file;
    }
}

if (! function_exists('img_url')) {
    /**
     * URL of one size of an image. Carries ?v=<file time>, so a photo replaced
     * in the media library is fetched again rather than served from a cache.
     */
    function img_url(string $key, string $size = '640'): string
    {
        $path = "assets/img/machines/{$key}-{$size}.webp";
        $file = FCPATH . $path;

        return base_url($path) . (is_file($file) ? '?v=' . filemtime($file) : '');
    }
}

if (! function_exists('photo_url')) {
    /**
     * URL for a photo referenced by key, as news articles do. Library images
     * resolve through img_url(); anything else falls back to the single file
     * news photos used before they joined the library: assets/img/<key>.webp.
     */
    function photo_url(string $key, string $size = '1600'): string
    {
        $key = trim($key, '/');

        return isset(timb_manifest()[$key])
            ? img_url($key, $size)
            : base_url('assets/img/' . $key . '.webp');
    }
}

if (! function_exists('img_tag')) {
    /** <img> with intrinsic width/height (prevents layout shift). $attrs are escaped. */
    function img_tag(string $key, string $size, string $alt, array $attrs = []): string
    {
        if ($key === '') {
            return ''; // no photo set for this item — not an error
        }

        $dims = timb_manifest()[$key]['files'][$size] ?? null;
        if ($dims === null) {
            log_message('error', "Unknown image key: {$key} ({$size})");

            return '';
        }

        // No alt given for a picture that carries meaning: use the description
        // stored in the media library. Decorative images pass role=presentation.
        if ($alt === '' && ($attrs['role'] ?? '') !== 'presentation') {
            $alt = (string) (timb_manifest()[$key]['alt'] ?? '');
        }

        $attrs = ['src' => img_url($key, $size), 'alt' => $alt, 'width' => $dims[0], 'height' => $dims[1], 'decoding' => 'async'] + $attrs;
        $html  = '';
        foreach ($attrs as $name => $value) {
            $html .= ' ' . $name . '="' . esc((string) $value, 'attr') . '"';
        }

        return '<img' . $html . '>';
    }
}

if (! function_exists('timb_path')) {
    /**
     * The requested path with a leading slash, the front controller removed
     * and no query string: /about, never /index.php/about.
     *
     * Whether index.php appears depends on how the server rewrites URLs, so
     * anything comparing the path against stored data has to strip it.
     */
    function timb_path(?string $path = null): string
    {
        $path ??= current_url(true)->getPath();
        $path = ltrim((string) $path, '/');

        if ($path === 'index.php' || str_starts_with($path, 'index.php/')) {
            $path = ltrim(substr($path, strlen('index.php')), '/');
        }

        return '/' . $path;
    }
}

if (! function_exists('asset_url')) {
    /** Public asset URL with ?v=<mtime> cache-busting. */
    function asset_url(string $path): string
    {
        $file = FCPATH . ltrim($path, '/');

        return base_url($path) . (is_file($file) ? '?v=' . filemtime($file) : '');
    }
}

if (! function_exists('india_xy')) {
    /**
     * Lat/lon -> [x%, y%] inside the India map SVG (see partials/india_map.php).
     * Map bounds: lon 68.0–97.6, lat 6.5–37.3.
     */
    function india_xy(float $lat, float $lon): array
    {
        return [round(($lon - 68.0) / 29.6 * 100, 2), round((37.3 - $lat) / 30.8 * 100, 2)];
    }
}

if (! function_exists('safe_inline')) {
    /**
     * Text that may carry a little formatting — a line break in a stats
     * caption, bold in a spec sheet line — made safe to print.
     *
     * Everything is escaped, then only <br>, <strong>, <b> and <em> are let
     * back in, with no attributes. These strings are edited in the CMS, so
     * they are never printed raw: a <script> or onclick= typed into a caption
     * comes out as harmless text.
     */
    function safe_inline(?string $text): string
    {
        $out = esc((string) $text);

        return (string) preg_replace(
            '#&lt;(/?)(br|strong|b|em)\s*/?&gt;#i',
            '<$1$2>',
            $out
        );
    }
}

if (! function_exists('form_stamp')) {
    /**
     * A hidden field recording when a public form was opened, signed so it
     * cannot be forged. form_stamp_age() reads it back. A bot posting straight
     * at the form either has no stamp or submits within a second or two.
     */
    function form_stamp(): string
    {
        $time = (string) time();

        return '<input type="hidden" name="form_ts" value="' . esc($time . '.' . timb_form_signature($time), 'attr') . '">';
    }

    /** Seconds since the form was opened, or null if the stamp is missing, forged or over a day old. */
    function form_stamp_age(?string $stamp): ?int
    {
        [$time, $sig] = array_pad(explode('.', (string) $stamp, 2), 2, '');

        if (! ctype_digit($time) || ! hash_equals(timb_form_signature($time), $sig)) {
            return null;
        }

        $age = time() - (int) $time;

        return $age >= 0 && $age <= 86400 ? $age : null;
    }

    function timb_form_signature(string $time): string
    {
        $secret = (string) (config('Encryption')->key ?: hash_file('sha256', APPPATH . 'Config/App.php'));

        return hash_hmac('sha256', 'form|' . $time, $secret);
    }
}

if (! function_exists('admin_url')) {
    /**
     * Full address of an admin screen: admin_url('machines/edit/4'). Built
     * from the site's own base URL, so admin links keep working if the site
     * is served from a subfolder or needs index.php in its addresses.
     *
     * Accepts 'machines', '/admin/machines' or 'admin/machines' alike, so a
     * path stored as '/admin/…' can be passed straight through. A query
     * string and a trailing slash are kept as given.
     */
    function admin_url(string $path = ''): string
    {
        $path = ltrim($path, '/');
        if ($path === 'admin' || str_starts_with($path, 'admin/') || str_starts_with($path, 'admin?')) {
            $path = ltrim(substr($path, 5), '/');
        }

        $base = rtrim(site_url(), '/') . '/admin';

        return $path === '' ? $base : $base . (str_starts_with($path, '?') ? '' : '/') . $path;
    }
}

